export const TRIAL_SITE_CLIENT = "\n(()=>{'use strict';\nconst seed=window.__TRIAL_SITE_SEED__;\nconst qs=new URLSearchParams(location.search);\n// Read this only AFTER async published-page prefetch has hydrated the browser.\nconst publicOnly=p=>(window.__PUBLIC_PAGE_IDS__||[]).includes(p.id);\nconst celebration=String(seed.celebrationId);\nconst KEY='celebrations-demo-preparation-'+celebration;\nconst GENERAL_KEY='celebrations-demo-shared-pages-v1',PLANS_KEY='celebrations-demo-planned-v1';\nfunction generalPages(){\n try{\n  const saved=JSON.parse(localStorage.getItem(GENERAL_KEY)||'null');\n  const rows=Array.isArray(saved?.pages)?saved.pages.filter(p=>p&&p.group==='page'&&publicOnly(p)&&Array.isArray(p.blocks)&&\n   (p.id==='neutral-accueil-general'||/^neutral-[0-9a-f-]{30,45}$/.test(p.id))):[];\n  const photo=seed.pages.find(p=>p.id==='neutral-accueil-general')?.blocks.find(b=>b.kind==='image')?.src;\n  for(const p of rows){\n   if(p.id==='neutral-accueil-general'&&photo&&\n    p.blocks.some(b=>b.kind==='heading'&&['Accueil général','Ronde des Archanges Universelle','Bienvenue sur le site de la Ronde des Archanges Universelle'].includes(b.text))&&\n    !p.blocks.some(b=>b.kind==='image'))p.blocks.push({id:99991,kind:'image',src:photo,text:'Ronde des Archanges Universelle',align:'center'});\n  }\n  return {pages:rows,homeId:rows.some(p=>p.id===saved.homeId)?saved.homeId:rows[0]?.id};\n }catch{return {pages:[],homeId:null}}\n}\nfunction celebrations(){\n let drafts=[];try{drafts=JSON.parse(localStorage.getItem(PLANS_KEY)||'[]')}catch{}\n drafts=Array.isArray(drafts)?drafts.filter(x=>/^plan-(michael|gabriel|raphael|ouriel)-\\d{4}-\\d{2}-\\d{2}$/.test(x.id)):[];\n for(let i=0;i<drafts.length;i++){\n  const cur=drafts[i],prev=drafts[i-1];\n  if(cur.customTitle&&cur.title)continue;\n  let year=Number(String(cur.date||cur.year||'').slice(0,4))||2027;\n  const priorStart=String(prev?.title||prev?.year||'').match(/20\\d{2}/)?.[0];\n  const priorEnd=[...String(prev?.title||prev?.year||'').matchAll(/20\\d{2}/g)].at(-1)?.[0];\n  if(prev&&(prev.archangel==='Raphaël'&&cur.archangel==='Ouriel'||\n    prev.archangel==='Ouriel'&&cur.archangel==='Michaël'||\n    prev.archangel==='Michaël'&&cur.archangel==='Gabriel'))year=Number(priorStart)||year;\n  if(prev&&prev.archangel==='Gabriel'&&cur.archangel==='Raphaël')year=Number(priorEnd)||year;\n  cur.title=cur.archangel+' '+(cur.archangel==='Gabriel'?year+'-'+(year+1):year);\n }\n return [...(seed.celebrations||[]).map(p=>({id:String(p.id),archangel:p.archangel,year:p.year,title:p.archangel+' '+p.year})),...drafts].filter(p=>\n window.__PUBLIC_CELEBRATION_VISIBILITY__?.[p.id]!=='draft'&&\n window.__PUBLIC_CELEBRATION_VISIBILITY__?.[p.id]!=='hidden'&&p.visibility!=='draft'&&p.visibility!=='hidden');\n}\nlet pages=seed.pages,active=qs.get('page')||generalPages().homeId||'neutral-accueil-general',menuOpen=false,libraryFamily='all',audioFilter='all';\nconst slugOf=p=>p.group==='page'?p.id:String(p.id).endsWith('-'+celebration)?\n String(p.id).slice(0,-celebration.length-1):p.id.slice(0,p.id.lastIndexOf('-'));\n\nconst DAYS=['mercredi','jeudi','vendredi','samedi','dimanche'];\nfunction validIso(value){\n if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(String(value||'')))return false;\n const [y,m,d]=value.split('-').map(Number),dt=new Date(Date.UTC(y,m-1,d));\n return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d;\n}\nfunction validWednesday(value){\n if(!validIso(value))return false;\n const [y,m,d]=value.split('-').map(Number);\n return new Date(Date.UTC(y,m-1,d)).getUTCDay()===3;\n}\nfunction formattedDate(iso){\n if(!validIso(iso))return '';\n const [y,m,d]=iso.split('-');return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(Number(y),Number(m)-1,Number(d))));\n}\nfunction dayIso(offset){\n if(!validWednesday(celebrationDates.wednesday)||offset<0||offset>4)return '';\n const [y,m,d]=celebrationDates.wednesday.split('-').map(Number);\n return new Date(Date.UTC(y,m-1,d+offset)).toISOString().slice(0,10);\n}\nfunction dateForPage(page){\n if(!page||page.group!=='celebration')return '';\n const slug=slugOf(page),n=DAYS.indexOf(slug);\n if(n!==-1)return formattedDate(dayIso(n));\n if(slug==='preparation')return celebrationDates.preparationDates.filter(validIso).map(formattedDate).join(' · ');\n return '';\n}\nfunction loadDates(saved){\n const data=saved?.celebrationDates&&typeof saved.celebrationDates==='object'?saved.celebrationDates:{};\n const defaultWednesday=validWednesday(seed.start_date)?seed.start_date:'';\n const get=(key,fallback='')=>Object.hasOwn(data,key)&&validIso(data[key])?data[key]:Object.hasOwn(data,key)?'':fallback;\n return {\n  wednesday:get('wednesday',defaultWednesday),\n  preparationDates:Array.isArray(data.preparationDates)?\n   data.preparationDates.filter(validIso).slice(0,30):\n   [get('preparationStart'),get('preparationEnd')].filter(validIso)\n };\n}\nlet celebrationDates=loadDates(null);\nfunction validClock(v){return typeof v==='string'&&/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/.test(v)}\nfunction loadTimes(saved){\n const raw=saved?.celebrationTimes;\n if(!raw||typeof raw!=='object'||Array.isArray(raw))return {};\n return Object.fromEntries(DAYS.filter(d=>validClock(raw[d])).map(d=>[d,raw[d]]));\n}\nlet celebrationTimes=loadTimes(null);\nfunction timeForPage(page){\n const slug=slugOf(page);\n return page?.group==='celebration'&&DAYS.includes(slug)?celebrationTimes[slug]||'':'';\n}\nfunction skipLegacyDateLines(rows){\n if(!celebration.startsWith('plan-'))return rows;\n for(const page of rows){\n  const original=seed.pages.find(x=>x.id===page.id)?.blocks.find(x=>x.id===2);\n  if(!original||!/^Date : \\d{4}-\\d{2}-\\d{2}$/.test(original.text||''))continue;\n  page.blocks=page.blocks.filter(x=>!(x.id===2&&x.kind==='text'&&x.text===original.text&&!x.rich&&!x.bold&&!x.italic&&!x.color&&!x.size));\n }\n return rows;\n}\n\nfunction mergePages(saved){\n if(!saved||!Array.isArray(saved.pages))return seed.pages.filter(publicOnly);\n const byId=new Map(saved.pages.filter(p=>p&&typeof p.id==='string'&&Array.isArray(p.blocks)&&['page','celebration'].includes(p.group)).map(p=>[p.id,p]));\n const original=seed.pages.map(p=>{\n  const old=byId.get(p.id);if(!old)return p;\n  if(p.id==='apres-celebration-'+celebration&&old.name==='Après préparation')old.name='Après célébration';\n  if(p.id==='accueil-celebration-'+celebration){\n   for(const block of p.blocks.filter(x=>Number(x.id)>100000)){\n    if(!old.blocks.some(x=>x.id===block.id))old.blocks.push(block);\n   }\n  }\n  return old;\n });\n const known=new Set(seed.pages.map(p=>p.id));\n const extra=saved.pages.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<105&&Array.isArray(p.blocks)&&p.blocks.length<300&&!known.has(p.id)&&(\n  (p.group==='page'&&/^neutral-[0-9a-f-]{30,45}$/.test(p.id))||(p.group==='celebration'&&p.id.startsWith('extra-')&&p.id.endsWith('-'+celebration))\n ));\n const result=original.concat(extra.slice(0,30)).filter(publicOnly);\n const shared=generalPages();\n return shared.pages.length?result.filter(p=>p.group!=='page').concat(shared.pages):result;\n}\n// A single colourway per archangel; the palette controls are gone.\nlet themeIndex=0;\nfunction isBoilerplateTitle(page,block){\n return page?.group==='celebration'&&block?.id===1&&block.kind==='heading'&&\n String(block.text||'').trim()===String(page.name||'').trim()&&\n !block.rich&&!block.bold&&!block.italic&&!block.color&&!block.size&&\n (!block.align||block.align==='center');\n}\nfunction omitBoilerplateTitles(rows){\n for(const page of rows)if(isBoilerplateTitle(page,page.blocks?.[0]))page.blocks.shift();\n return rows;\n}\ntry{\n const saved=JSON.parse(localStorage.getItem(KEY)||'null');\n if(saved&&Array.isArray(saved.pages)){\n  pages=skipLegacyDateLines(omitBoilerplateTitles(mergePages(saved)));\n  celebrationDates=loadDates(saved);\n  celebrationTimes=loadTimes(saved);\n\n }\n}catch{}\npages=skipLegacyDateLines(omitBoilerplateTitles(mergePages({pages})));\nif(!pages.some(p=>slugOf(p)===active)&&!['celebrations','mediatheque','mediatheque-generale'].includes(active))active=generalPages().homeId||'neutral-accueil-general';\nconst el=id=>document.getElementById(id);\nconst make=(tag,className,text)=>{const x=document.createElement(tag);if(className)x.className=className;if(text!==undefined)x.textContent=String(text);return x};\nfunction urlOk(v){\n const s=String(v||'').trim();\n if(!s||s.length>2500||/[\\\\\\u0000-\\u001f]/.test(s))return '';\n if(s.startsWith('/')&&!s.startsWith('//'))return s;\n try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.toString():''}catch{return ''}\n}\nconst colors=/^#[0-9a-f]{6}$/i;\n\nfunction applyCelebrationPalette(){\n const set=Array.isArray(seed.palettes)?seed.palettes:[];\n const variant=set[0];\n if(!variant||!Array.isArray(variant.shades)||variant.shades.length!==5)return;\n const root=document.documentElement;\n if(/^#[0-9a-f]{6}$/i.test(variant.shades[3]))root.style.setProperty('--frame-color',variant.shades[3]);\n const label=el('palette-label');\n if(label)label.textContent=variant.name;\n}\n\n// Strict allowlist: preview renders only inline bold, italic and hexadecimal RGB colours.\nfunction inlineTextColor(value){\n const v=String(value||'').trim().toLowerCase();\n if(/^#[0-9a-f]{6}$/.test(v))return v;\n const match=v.match(/^rgb\\(([^)]+)\\)$/);\n if(!match)return '';\n const values=match[1].split(/[\\s,]+/).filter(Boolean);\n if(values.length!==3||values.some(n=>!/^\\d{1,3}$/.test(n)||Number(n)>255))return '';\n return '#'+values.map(n=>Number(n).toString(16).padStart(2,'0')).join('');\n}\nfunction formattedText(host,b){\n if(typeof b.rich!=='string'||!b.rich){\n  host.textContent=String(b.text||'');\n  return;\n }\n const temp=document.createElement('template');\n temp.innerHTML=b.rich.slice(0,18000);\n let count=0;\n const allowed=new Map([['B','strong'],['STRONG','strong'],['I','em'],['EM','em'],['BR','br']]);\n function copy(node,target){\n  if(count++>12000)return;\n  if(node.nodeType===3){target.append(document.createTextNode(node.textContent||''));return}\n  if(node.nodeType!==1&&node.nodeType!==11)return;\n  const tag=node.nodeType===1?node.tagName:'';\n  if(['SCRIPT','STYLE','SVG','IFRAME','OBJECT','TEMPLATE'].includes(tag))return;\n  if(tag==='BR'){target.append(make('br'));return}\n  let wrapper=allowed.get(tag)?make(allowed.get(tag)):target;\n  if(tag==='SPAN'||tag==='FONT'){\n   const raw=node.getAttribute('style')||'';\n   const specified=raw.match(/(?:^|;)\\s*color\\s*:\\s*([^;]+)(?:;|$)/i);\n   const color=inlineTextColor(tag==='FONT'?node.getAttribute('color')||node.style.color:(specified?.[1]||node.style.color));\n   if(color){wrapper=make('span');wrapper.style.color=color}\n  }\n  for(const child of node.childNodes)copy(child,wrapper);\n  if(wrapper!==target)target.append(wrapper);\n }\n copy(temp.content,host);\n}\nfunction applyStyle(node,b){\n node.style.textAlign=['left','center','right'].includes(b.align)?b.align:'left';\n if(b.bold)node.style.fontWeight='700';\n if(b.italic)node.style.fontStyle='italic';\n if(colors.test(b.color||''))node.style.color=b.color;\n const size=Number(b.size);\n if([14,16,18,20,24,28,32,40].includes(size))node.style.fontSize=size+'px';\n}\nconst blobUrls=new Map();\nfunction openStore(){return new Promise((ok,no)=>{if(!indexedDB){no(Error('IndexedDB'));return}const q=indexedDB.open('celebrations-demo-files-v1',1);q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('files'))q.result.createObjectStore('files',{keyPath:'id'})}})}\nasync function loadAssets(){\n const ids=new Set(pages.flatMap(p=>p.blocks.map(b=>b.assetId)).filter(x=>typeof x==='string'));\n if(ids.size===0)return;\n let db;\n try{db=await openStore()}catch{return}\n try{await Promise.all([...ids].map(id=>new Promise(resolve=>{\n  const tx=db.transaction('files','readonly'),r=tx.objectStore('files').get(id);\n  r.onsuccess=()=>{if(r.result&&r.result.blob)blobUrls.set(id,URL.createObjectURL(r.result.blob));resolve()};\n  r.onerror=()=>resolve();\n })))}catch{}finally{db.close()}\n}\nfunction collectMedia(blocks,items,page){\n for(const block of blocks||[]){\n  if(block.kind==='section'){for(const col of block.columns||[])collectMedia(col,items,page);continue}\n  // Navigation links are not media; only actual file links are indexed.\n  const href=String(block.href||'');\n  const extension=href.split(/[?#]/)[0].toLowerCase();\n  const fileKind=/\\.pdf$/.test(extension)?'pdf':\n   /\\.(?:mp3|wav|ogg|m4a|flac)$/.test(extension)?'audio':\n   /\\.(?:jpe?g|png|gif|webp|avif|svg)$/.test(extension)?'image':\n   /\\.(?:mp4|webm|mov)$/.test(extension)?'video':\n   /\\.(?:txt|csv|docx?|odt|rtf|zip|epub)$/.test(extension)?'file':null;\n  const type=block.kind==='image'?'image':block.kind==='video'?'video':\n   block.kind==='audio'?'audio':block.kind==='button'?fileKind:null;\n  const src=block.kind==='video'||block.kind==='button'?block.href:block.src;\n  if(!type||!urlOk(src))continue;\n  const id=type+'|'+src;\n  if(!items.has(id))items.set(id,{id,name:String(block.text||'Média').slice(0,120),\n   type,src,external:type==='video'?src:undefined,pages:[page]});\n  else if(!items.get(id).pages.includes(page))items.get(id).pages.push(page);\n }\n}\nfunction galleryEntries(general=false){\n if(general)return (window.__PUBLIC_MEDIA__||[])\n  // The public server already filters drafts, hidden pages and private files.\n  // Do not re-filter by 'general': this omitted normal published page media.\n  .filter(x=>['image','video','audio','pdf','file'].includes(x.type)&&urlOk(x.src||x.external))\n  .map(x=>({...x,pages:(x.uses||[]).map(u=>u.pageName).filter(Boolean)}));\n if(!window.__PUBLIC_CELEBRATION_VISIBLE__)return [];\n const visiblePageNames=new Set(pages.filter(p=>p.group==='celebration').map(p=>p.name));\n const catalogue=(Array.isArray(seed.library)?seed.library:[]).filter(x=>x&&\n  ['audio','video','pdf','image','file'].includes(x.type)&&Array.isArray(x.pages)&&\n  x.pages.some(name=>visiblePageNames.has(name)));\n const items=new Map(catalogue.map(x=>[x.type+'|'+(x.src||x.external),x]));\n for(const page of pages.filter(p=>p.group==='celebration'))collectMedia(page.blocks,items,page.name);\n return [...items.values()];\n}\nfunction youtubeEmbed(url){\n try{\n  const u=new URL(url),h=u.hostname.toLowerCase();\n  const id=h==='youtu.be'?u.pathname.slice(1):['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(h)\n   ?u.searchParams.get('v')||(u.pathname.match(/^\\/(?:embed|shorts)\\/([\\w-]{11})/)||[])[1]:'';\n  return /^[\\w-]{11}$/.test(id||'')?'https://www.youtube-nocookie.com/embed/'+id:'';\n }catch{return ''}\n}\n// Each media item is a genuine link: right-click can open the original file\n// in a new tab. A normal click on audio/video expands the player in-place.\nfunction galleryCard(item,general=false){\n const card=make('article','media-card compact-media');\n const location=make('small','media-location',(item.pages||[]).join(' · '));location.hidden=general;\n const url=urlOk(item.src||item.external);\n if(item.type==='image'){\n  const imageUrl=urlOk(item.src||item.cover);\n  if(imageUrl){\n   const link=make('a','media-image-link');link.href=imageUrl;link.target='_blank';link.rel='noopener noreferrer';\n   const image=make('img','media-image');image.src=imageUrl;image.alt=item.name;image.loading='lazy';link.append(image);card.append(link);\n  }\n  card.append(make('div','media-image-name',item.name),location);return card;\n }\n if(item.type==='text'){\n  const details=make('details','media-text'),label=make('summary','media-item-link',item.name),body=make('p','',item.text||item.description||'');\n  details.append(label,body);card.append(details,location);return card;\n }\n const link=make('a','media-item-link',item.name);\n if(url){link.href=url;link.target='_blank';link.rel='noopener noreferrer'}\n else link.removeAttribute('href');\n card.append(link,location);\n if(item.type==='pdf')return card;\n if(item.type==='audio'||item.type==='video'){\n  const panel=make('div','media-inline-player');panel.hidden=true;\n  if(item.type==='audio'&&url){\n   const audio=make('audio','media-player');audio.controls=true;audio.preload='none';audio.src=url;panel.append(audio);\n   const controls=make('div','media-seek');\n   for(const [text,seconds] of [['−10 s',-10],['+10 s',10]]){\n    const button=make('button','media-small-button',text);button.type='button';\n    button.onclick=()=>{try{audio.currentTime=Math.max(0,Math.min(Number.isFinite(audio.duration)?audio.duration:Infinity,audio.currentTime+seconds))}catch{}};\n    controls.append(button);\n   }\n   const repeat=make('label','media-repeat'),check=make('input');check.type='checkbox';\n   check.onchange=()=>audio.loop=check.checked;repeat.append(check,document.createTextNode(' En boucle'));\n   panel.append(controls,repeat);\n  }else if(item.type==='video'){\n   const embed=youtubeEmbed(item.external);\n   if(url&&/\\\\.(?:mp4|webm|ogg)$/i.test(url)){\n    const video=make('video','media-video');video.controls=true;video.preload='none';video.src=url;panel.append(video);\n   }else if(embed){\n    const wrap=make('div','video-container'),frame=make('iframe','media-video');\n    frame.src=embed;frame.title=item.name;frame.loading='lazy';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;wrap.append(frame);panel.append(wrap);\n   }\n  }\n  if(panel.childElementCount){\n   // Close opened videos without leaving a dark player on the page.\n   if(item.type==='video'){\n    const close=make('button','media-video-close','×');close.type='button';\n    close.title='Fermer la vidéo';close.setAttribute('aria-label','Fermer la vidéo');\n    close.onclick=()=>{\n     const frame=panel.querySelector('iframe');\n     if(frame){frame.dataset.originalSrc=frame.dataset.originalSrc||frame.getAttribute('src')||'';frame.removeAttribute('src')}\n     const player=panel.querySelector('video');if(player)player.pause();\n     panel.hidden=true;link.setAttribute('aria-expanded','false');\n    };\n    panel.prepend(close);\n   }\n   link.onclick=event=>{\n    if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;\n    event.preventDefault();panel.hidden=!panel.hidden;\n    if(!panel.hidden){\n     const frame=panel.querySelector('iframe');\n     if(frame&&!frame.getAttribute('src')&&frame.dataset.originalSrc)frame.src=frame.dataset.originalSrc;\n    }\n    link.setAttribute('aria-expanded',String(!panel.hidden));\n    if(panel.hidden){const player=panel.querySelector('audio,video');if(player)player.pause()}\n   };\n   link.setAttribute('aria-expanded','false');card.append(panel);\n  }\n }\n return card;\n}\nfunction renderGallery(main,general=false){\n const all=galleryEntries(general),tabs=make('div','media-tabs');\n if(general)main.append(make('h2','page-title','Médiathèque générale'));\n for(const [category,label] of [['all','Tous les fichiers'],['image','Images'],['audio','Audio'],['video','Vidéos'],['text','Documents (PDF et fichiers)']]){\n  const button=make('button',libraryFamily===category?'media-tab current':'media-tab',label);\n  button.type='button';button.onclick=()=>{libraryFamily=category;audioFilter='all';render()};tabs.append(button);\n }\n main.append(tabs);\n if(libraryFamily==='audio'){\n  const filters=make('div','media-filters');\n  for(const [v,label] of [['all','Tous'],['chant','Chants'],['other','Audios parlés']]){\n   const button=make('button',audioFilter===v?'media-filter current':'media-filter',label);\n   button.type='button';button.onclick=()=>{audioFilter=v;render()};filters.append(button);\n  }\n  main.append(filters);\n }\n const list=make('div',libraryFamily==='image'?'media-list media-image-grid':'media-list');\n const matching=all.filter(x=>libraryFamily==='all'||(libraryFamily==='text'?['pdf','file'].includes(x.type):x.type===libraryFamily))\n  .filter(x=>libraryFamily!=='audio'||audioFilter==='all'||(audioFilter==='chant'?x.chant:!x.chant));\n for(const item of matching)list.append(galleryCard(item,general));\n if(!matching.length)list.append(make('p','media-empty','Aucun contenu'));\n main.append(list);\n}\n\nfunction go(slug){active=slug;menuOpen=false;history.replaceState(null,'','?celebration='+encodeURIComponent(celebration)+'&page='+encodeURIComponent(slug));render();window.scrollTo({top:0,behavior:'instant'});}\nfunction render(){\n const listing=active==='celebrations',isGeneralGallery=active==='mediatheque-generale',\n isGallery=active==='mediatheque'||isGeneralGallery;\n const requested=pages.find(p=>slugOf(p)===active);\n const page=requested||pages.find(p=>p.group==='page')||pages[0]||\n  {id:'page-indisponible',name:'Page indisponible',group:'page',blocks:[]};\n const unpublished=!(listing||isGallery)&&!requested;\n const neutral=listing||isGeneralGallery||(!isGallery&&page.group==='page');\n document.body.classList.toggle('is-neutral-preview',neutral);\n applyCelebrationPalette();\n const shortcuts=el('celebration-shortcuts');shortcuts.replaceChildren();\n for(const [slug,label] of [['preparation','Programme'],['mediatheque','Médiathèque']]){\n  const selected=slug==='mediatheque'?active==='mediatheque':slug==='accueil-celebration'?active==='accueil-celebration':!neutral&&!isGallery;\n  const button=make('button',selected?'celebration-shortcut current':'celebration-shortcut',label);\n  button.type='button';button.onclick=()=>go(slug);shortcuts.append(button);\n }\n shortcuts.hidden=listing||isGeneralGallery||(!isGallery&&page.group==='page');\n const nav=el('stage-navigation');nav.replaceChildren();\n nav.after(shortcuts);\n for(const p of pages.filter(p=>p.group==='celebration')){\n  const slug=slugOf(p),date=dateForPage(p);\n  const label=p.name+(date&&DAYS.includes(slug)?' · '+date:'');\n  const bt=make('button',slug===active?'stage-tab current':'stage-tab',label);\n  bt.type='button';bt.onclick=()=>go(slug);nav.append(bt);\n }\n nav.hidden=neutral||isGallery;\n const general=el('general-navigation');general.replaceChildren();\n const homeId=generalPages().homeId||'neutral-accueil-general';\n for(const p of pages.filter(p=>p.group==='page'&&slugOf(p)!==homeId)){\n  const item=make('button',slugOf(p)===active?'general-tab current':'general-tab',p.name);\n  item.type='button';item.onclick=()=>go(slugOf(p));general.append(item);\n }\n const home=make('button',active===homeId?'general-tab current':'general-tab','⌂ Accueil');\n home.type='button';home.onclick=()=>go(homeId);general.prepend(home);\n const all=make('button',listing?'general-tab current':'general-tab','✧ Célébrations');\n all.type='button';all.onclick=()=>go('celebrations');general.append(all);\n const library=make('button',isGeneralGallery?'general-tab current':'general-tab','▧ Médiathèque générale');\n library.type='button';library.onclick=()=>go('mediatheque-generale');general.append(library);\n const menu=el('menu-toggle');\n if(menu)menu.onclick=()=>{menuOpen=!menuOpen;general.hidden=!menuOpen;menu.setAttribute('aria-expanded',String(menuOpen))};\n general.hidden=!menuOpen;\n if(menu)menu.setAttribute('aria-expanded',String(menuOpen));\n const back=el('return-celebration');if(back){back.hidden=!neutral;back.onclick=()=>go('accueil-celebration')}\n document.title=(listing?'Célébrations':isGallery?'Médiathèque':page.name)+(location.hostname.endsWith('ronde-des-archanges-universelle.eu')?' — Célébrations des Archanges':' — Site d’essai');\n el('back-admin').href='/__editor/demo-preparation?celebration='+encodeURIComponent(celebration)+'&page='+encodeURIComponent(active);\n const main=el('stage-main');main.replaceChildren();\n if(!listing&&!isGallery&&page.group==='celebration'){\n  const date=dateForPage(page),hour=timeForPage(page),display=[date,hour].filter(Boolean).join(' · ');\n  if(display){const label=make('div','site-page-date',display);label.dataset.role='celebration-date';main.append(label)}\n }\n if(isGallery){renderGallery(main,isGeneralGallery);return}\n if(unpublished){main.append(make('p','media-empty','Cette page n’est pas publiée.'));return}\n if(listing){\n  const choices=make('div','celebration-choices');\n  for(const entry of celebrations()){\n   const card=make('a','celebration-choice');\n   card.href='/__editor/voir-le-site?celebration='+encodeURIComponent(entry.id)+'&page=accueil-celebration';\n   card.append(make('strong','',entry.title||entry.archangel+' '+entry.year));\n   card.append(make('small','',entry.kind==='planned'?'En préparation (test)':'Voir les pages de la célébration'));\n   choices.append(card);\n  }\n  main.append(choices);return;\n }\n let mainHeadingRendered=false;\n function siteVideoInfo(href){\n  try{\n   const u=new URL(href),host=u.hostname.toLowerCase();let id='';\n   if(['youtu.be','www.youtu.be'].includes(host))id=u.pathname.split('/')[1];\n   else if(['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(host))\n    id=u.searchParams.get('v')||(u.pathname.match(/^\\/(?:embed|shorts|live)\\/([\\w-]{11})/)||[])[1];\n   if(/^[\\w-]{11}$/.test(id||''))return {thumbnail:'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg',embed:'https://www.youtube-nocookie.com/embed/'+id};\n   if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(host)){\n    const m=u.pathname.match(/(?:\\/video)?\\/(\\d{6,12})(?:\\/|$)/);\n    if(m)return {thumbnail:'https://vumbnail.com/'+m[1]+'.jpg',embed:'https://player.vimeo.com/video/'+m[1]};\n   }\n  }catch{}\n  return null;\n }\n function siteLinkCard(href,title){\n  const el=make('div','trial-website-card');\n  try{\n   const url=new URL(href);\n   const icon=make('img','trial-website-icon');icon.src=url.origin+'/favicon.ico';icon.alt='';\n   icon.onerror=()=>icon.remove();el.append(icon,make('span','trial-website-domain',url.hostname));\n  }catch{}\n  el.append(make('strong','',title||'Site'));return el;\n }\n function appendPageBlock(b,root){\n  if(!b)return;\n  if(b.kind==='section'){\n   const st=b.style||{},frame=['none','round','square'].includes(st.border)?st.border:'none';\n   const section=make('section','trial-content-section');\n   section.dataset.layout=b.layout==='columns'?'columns':'single';\n   if(frame!=='none'){\n    section.style.border=Math.min(5,Math.max(1,Number(st.width)||1))+'px solid '+(/^#[0-9a-f]{6}$/i.test(st.color)?st.color:'#d7dde5');\n    section.style.borderRadius=frame==='round'?'16px':'0';\n   }\n   if(st.shadow)section.style.boxShadow='0 5px 19px #16243329';\n   const columns=make('div','trial-content-columns');\n   const arrays=Array.isArray(b.columns)?b.columns:[[],[]];\n   if(b.layout==='columns'){\n    for(const items of arrays.slice(0,2)){\n     const cell=make('div','trial-content-column');\n     for(const child of items||[])appendPageBlock(child,cell);\n     columns.append(cell);\n    }\n   }else{\n    const cell=make('div','trial-content-column');\n    for(const items of arrays.slice(0,2))for(const child of items||[])appendPageBlock(child,cell);\n    columns.append(cell);\n   }\n   section.append(columns);root.append(section);return;\n  }\n  if(!['heading','event','text','image','button','audio','video'].includes(b.kind))return;\n  // Older celebrations stored linked videos as buttons: show their real\n  // player and thumbnail without rewriting the historic content.\n  if(b.kind==='button'){\n   const href=urlOk(b.href);\n   if(siteVideoInfo(href)||/\\.(?:mp4|webm|ogg)(?:\\?|$)/i.test(href||'')){\n    appendPageBlock({...b,kind:'video'},root);return;\n   }\n  }\n  const wrap=make('div','site-block');\n  if(b.kind!=='event'&&validClock(b.atTime)){const marker=make('time','media-at-time',b.atTime);wrap.append(marker)}\n  if(b.kind==='heading'||b.kind==='event'){\n   const primary=!mainHeadingRendered;mainHeadingRendered=true;\n   const isSchedule=/^[0-2]?[0-9]:[0-5][0-9][ ]*[—–-]/.test(String(b.text||''));\n   const h=make(primary?'h1':'h2','trial-heading '+(primary?'heading-primary':'heading-secondary')+(isSchedule||b.kind==='event'?' heading-schedule':''));\n   formattedText(h,b);\n   if(b.kind==='event'&&validClock(b.atTime)&&!/^\\d{1,2}:\\d{2}\\s*[—–-]/.test(String(b.text||''))){\n    const time=make('time','event-inline-time',b.atTime+' — ');h.prepend(time);\n   }\n   applyStyle(h,b);wrap.append(h);\n  }else if(b.kind==='text'){\n   const p=make('p','trial-paragraph');formattedText(p,b);applyStyle(p,b);wrap.append(p);\n  }else if(b.kind==='image'){\n   const src=b.assetId?blobUrls.get(b.assetId):urlOk(b.src);\n   if(src){\n    const fig=make('figure','trial-figure'),img=make('img');\n    const width=Number.isInteger(b.widthPct)&&b.widthPct>=20&&b.widthPct<=100?b.widthPct:100;\n    fig.style.width=width+'%';fig.style.maxWidth='100%';fig.style.marginLeft='auto';fig.style.marginRight='auto';\n    img.src=src;img.alt=String(b.text||'Illustration');img.loading='lazy';img.style.width='100%';img.style.height='auto';\n    fig.append(img);wrap.append(fig);\n   }\n  }else if(b.kind==='audio'){\n   const box=make('div','trial-audio');\n   box.append(make('strong','',String(b.text||'Enregistrement MP3')));\n   const remote=/^editor-trials\\/audio\\/[0-9a-f-]{36}\\.mp3$/.test(String(b.remoteKey||''));\n   const src=remote?'/api/editor-trial-audio?action=stream&key='+encodeURIComponent(b.remoteKey):\n     /^\\/media\\/(?!.*\\.\\.)[^?#]+\\.mp3$/i.test(String(b.src||''))?b.src:'';\n   if(src){const audio=make('audio','trial-audio-player');audio.controls=true;audio.preload='none';audio.src=src;box.append(audio)}\n   else box.append(make('p','trial-unavailable','MP3 indisponible dans cet aperçu.'));\n   wrap.append(box);\n  }else if(b.kind==='video'){\n   const href=urlOk(b.href),video=siteVideoInfo(href);\n   const container=make('div','trial-video');\n   const title=make('div','trial-video-title',b.text||'Vidéo');\n   const cover=b.coverAssetId?blobUrls.get(b.coverAssetId):urlOk(b.cover);\n   const image=video?.thumbnail||cover;\n   if(href&&video){\n    const toggle=make('button','trial-video-trigger');\n    toggle.type='button';toggle.setAttribute('aria-label','Lire la vidéo');\n    if(image){const thumb=make('img','trial-video-thumb');thumb.src=image;thumb.alt=b.text||'Vidéo';thumb.loading='lazy';toggle.append(thumb)}\n    toggle.append(make('span','trial-video-play','▶'));container.append(toggle,title);\n    toggle.onclick=()=>{\n     const iframe=make('iframe','trial-video-iframe');iframe.src=video.embed;\n     iframe.title=b.text||'Vidéo';iframe.loading='lazy';iframe.referrerPolicy='strict-origin-when-cross-origin';\n     iframe.allow='accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture';iframe.allowFullscreen=true;\n     toggle.replaceWith(iframe);\n    };\n   }else if(href&&/\\\\.(?:mp4|webm|ogg)(?:$|\\?)/i.test(href)){\n    const player=make('video','trial-video-player');player.controls=true;player.preload='none';player.src=href;\n    if(cover)player.poster=cover;container.append(player,title);\n   }else if(href){\n    const a=make('a','trial-site-link');a.href=href;a.target='_blank';a.rel='noopener noreferrer';\n    if(cover){const thumb=make('img','trial-site-cover');thumb.src=cover;thumb.alt=b.text||'Site';a.append(thumb)}\n    else a.append(siteLinkCard(href,b.text||'Site'));\n    a.append(title);container.append(a);\n   }else container.append(make('span','trial-unavailable','Vidéo à ajouter'));\n   wrap.append(container);\n  }else if(b.kind==='button'){\n   const href=b.assetId?blobUrls.get(b.assetId):urlOk(b.href);\n   if(href){\n    const link=make('a','trial-button',b.text||'Ouvrir');\n    link.href=href;link.rel='noopener noreferrer';link.target='_blank';applyStyle(link,b);\n    const cover=b.coverAssetId?blobUrls.get(b.coverAssetId):urlOk(b.cover);\n    const video=siteVideoInfo(href);\n    if(video){\n     link.className='trial-site-link';\n     const img=make('img','trial-site-cover');img.src=video.thumbnail;img.alt=b.text||'Vidéo';img.loading='lazy';\n     link.prepend(img);\n    }else if(cover){\n     link.className='trial-site-link';\n     const img=make('img','trial-site-cover');img.src=cover;img.alt=b.text||'Site';img.loading='lazy';\n     link.prepend(img);\n    }else if(/^https:\\/\\//.test(href)&&!href.endsWith('.pdf')){\n     link.className='trial-site-link';link.prepend(siteLinkCard(href,b.text||'Site'));\n    }\n    wrap.append(link);\n   }\n   else {const note=make('span','trial-unavailable',b.text||'Document indisponible');wrap.append(note)}\n  }\n  root.append(wrap);\n }\n for(const b of page.blocks||[])appendPageBlock(b,main);\n}\nrender();\nloadAssets().then(render);\nwindow.addEventListener('storage',e=>{if(e.key===KEY){try{const fresh=JSON.parse(e.newValue);if(fresh&&Array.isArray(fresh.pages)){const byId=new Map(fresh.pages.map(p=>[p.id,p]));pages=skipLegacyDateLines(omitBoilerplateTitles(mergePages(fresh)));celebrationDates=loadDates(fresh);celebrationTimes=loadTimes(fresh);render()}}catch{}}});\n})();\n";
export const TRIAL_SITE_STYLE = "\n:root{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;color:#263747;background:#f7f4ef}\n*{box-sizing:border-box}\nhtml{width:100%;max-width:100%;overflow-x:hidden}\nbody{margin:0;width:100%;max-width:100%;overflow-x:hidden}\na,button{font:inherit}a:focus-visible,button:focus-visible{outline:3px solid #bc886a;outline-offset:3px}\n.trial-banner{background:#293746;color:#fff;padding:12px clamp(16px,4vw,48px);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}\n.trial-banner strong{font:16px Georgia,serif}.trial-banner small{display:block;font-size:11px;color:#d2d9dc;margin-top:4px}\n.back-admin{background:#fff;color:#293746;padding:10px 14px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700}\n.hero{padding:50px 18px 30px;text-align:center;background:#fff}\n.hero .tag{color:#ae775c;text-transform:uppercase;letter-spacing:3px;font-size:11px}\n.hero h1{font:clamp(30px,6vw,52px) Georgia,serif;line-height:1.2;margin:12px auto;color:#2c3944}\n.hero p{font-size:14px;color:#667580;margin:0}\n.steps{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;max-width:1200px;margin:0 auto;padding:20px 18px}\n.stage-tab{border:1px solid #e9e1d8;background:#fff;color:#505d65;border-radius:9px;padding:11px 6px;min-height:46px;font-size:13px;cursor:pointer;overflow-wrap:anywhere}\n.stage-tab.current{background:#ad6e52;border-color:#ad6e52;color:#fff;font-weight:700}\n.site-paper{max-width:940px;margin:14px auto 55px;background:#fff;border:1px solid #eee8e0;border-radius:12px;padding:clamp(26px,6vw,66px);box-shadow:0 6px 26px #2637470b;min-width:0}\n.site-paper h2#page-heading{font:clamp(30px,5vw,44px) Georgia,serif;text-align:center;line-height:1.2;color:#293746;margin:0 0 42px}\n.site-block{max-width:100%;min-width:0;overflow-wrap:anywhere;margin:0 0 24px}\n.trial-heading{font:30px/1.4 Georgia,serif;font-weight:400;margin:25px 0 10px;white-space:pre-wrap;overflow-wrap:anywhere}\n.trial-paragraph{font:16px/1.8 system-ui,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere;color:#505e68;margin:6px 0}\n.trial-figure{padding:0;margin:16px 0}.trial-figure img{max-width:100%;height:auto;border-radius:8px}\n.trial-button{display:inline-block;border:1px solid #ac7154;border-radius:8px;padding:11px 19px;color:#8e5138;text-decoration:none;max-width:100%;overflow-wrap:anywhere;font-weight:650}\n.trial-unavailable{font-size:13px;color:#997f74}\n.footer{padding:23px 16px;text-align:center;color:#78838c;font-size:12px}\n@media(max-width:850px){.steps{grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.site-paper{margin:10px 12px 40px}}\n@media(max-width:480px){.trial-banner{padding:12px 15px}.back-admin{width:100%;text-align:center}.hero{padding:33px 15px 20px}.steps{grid-template-columns:repeat(2,minmax(0,1fr));padding:13px 12px}.stage-tab{min-height:44px}.site-paper{padding:25px 19px;margin:8px 10px 38px}.site-paper h2#page-heading{margin-bottom:25px}}\n\n/* Neutral white/grey site throughout; the archangel shade is reserved for the celebration page frame. */\n:root{--tone-bg:#fff;--tone-light:#fafafa;--tone-soft:#eceff1;--tone-accent:#cfd4d8;--tone-deep:#aab0b5;--frame-color:#ea342f;color:#292e32;background:var(--tone-bg)}\nbody{background:var(--tone-bg);color:#292e32}\n.trial-banner{background:var(--tone-light);color:#292e32;border-bottom:2px solid var(--tone-soft)}\n.trial-banner strong,.trial-banner small{color:#292e32}\n.back-admin{background:#fff;color:#292e32;border:1px solid var(--tone-accent)}\n.hero{background:var(--tone-bg);border-bottom:1px solid var(--tone-soft)}\n.hero .tag{color:#494f54}\n.hero h1{color:#292e32}\n.hero p{color:#4b545a}\n.steps{background:var(--tone-bg)}\n.stage-tab{border-color:var(--tone-soft);color:#30353a;background:#fff}\n.stage-tab.current{background:var(--tone-soft);border-color:var(--tone-accent);color:#292e32}\n.site-paper{border-color:var(--tone-soft);box-shadow:0 7px 23px #292e320d}\n.site-paper h2#page-heading{color:#292e32}\n.trial-heading{color:#292e32}\n.trial-paragraph{color:#484f55}\n.trial-button{border-color:var(--tone-accent);background:var(--tone-light);color:#292e32}\n.trial-unavailable{color:#484f55}\n.footer{color:#484f55}\n.palette-description{font-size:12px;color:#4b545a;margin-top:9px}\n\n.steps[hidden],.general-navigation[hidden],.return-celebration[hidden]{display:none!important}\n.site-paper{border:6px solid var(--frame-color);border-radius:14px}\n.site-menu-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px clamp(12px,3vw,28px);background:var(--tone-light);border-top:1px solid var(--tone-soft);border-bottom:1px solid var(--tone-soft)}\n.site-menu-title{font-size:13px;color:#30373a;font-weight:600}\n.menu-toggle,.return-celebration{font:inherit;border:1px solid var(--tone-accent);border-radius:8px;background:white;padding:10px 14px;min-height:44px;color:#292e32;font-weight:700}\n.general-navigation{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:9px;padding:12px clamp(12px,3vw,28px);background:#fff;border-bottom:1px solid #e3e3e3}\n.general-tab{border:1px solid #d5d8db;background:#fff;border-radius:8px;padding:12px;text-align:left;color:#292e32}\n.general-tab.current{background:#eef0f2;font-weight:700}\nbody.is-neutral-preview{--tone-bg:#fff!important;--tone-light:#fafafa!important;--tone-soft:#e8ecef!important;--tone-accent:#d8dade!important;--tone-deep:#b9bdc1!important;background:#fff;color:#292e32}\nbody.is-neutral-preview .hero,body.is-neutral-preview .steps,body.is-neutral-preview .site-menu-bar{background:#fff}\nbody.is-neutral-preview .site-paper{border:2px solid #e7e9ec;box-shadow:none}\nbody.is-neutral-preview .trial-banner{background:#f8f9fa;color:#292e32}\nbody.is-neutral-preview .palette-description{display:none}\n@media(max-width:600px){.site-paper{border-width:4px}.site-menu-bar{padding:10px 12px}.site-menu-title{width:100%}}\n\n.trial-audio{display:grid;gap:12px;margin:18px 0;max-width:100%;background:#fafafa;border:1px solid #e3e5e7;padding:18px;border-radius:12px}.trial-audio-player{display:block;width:100%;max-width:100%}.trial-audio small{color:#5c646b}\n\n.celebration-choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}\n.celebration-choice{display:grid;gap:8px;border:1px solid #dce0e3;border-radius:12px;padding:20px;background:white;color:#252a2e;text-decoration:none}\n.celebration-choice:hover,.celebration-choice:focus-visible{border-color:#8b949d;background:#f7f8fa}\n.celebration-choice small{font-size:12px;color:#565e65}\n.site-menu-bar{position:sticky;top:0;z-index:5}\n\n/* Reader-mode preview: no instructional chrome, one discreet admin link at the bottom. */\nbody{min-height:100vh;display:flex;flex-direction:column}\n.hero{padding:20px 14px 10px}\n.hero h1{font-size:clamp(23px,4vw,33px);margin:6px auto}\nbody.is-neutral-preview .hero{display:none}\n.footer{margin-top:auto;padding:20px 16px 30px;text-align:center}\n.footer a{color:#30363b;font-size:13px;text-decoration:none;display:inline-block;padding:12px 18px;border-radius:8px}\n.footer a:hover,.footer a:focus-visible{color:#15181a;text-decoration:underline;background:#f2f3f4}\n@media(max-width:600px){.hero{padding:15px 12px 8px}}\n\n/* Celebration programme dates – the date is content metadata, not a fixed title. */\n.site-page-date{text-align:center;color:#42484e;font-size:15px;letter-spacing:.02em;margin:0 0 24px;font-weight:600}\n@media(max-width:600px){.site-page-date{font-size:14px;margin-bottom:18px}}\n\n.celebration-shortcuts{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:14px auto;max-width:980px;padding:0 10px}\n.celebration-shortcut{border:1px solid #cdd1d5;border-radius:26px;min-width:115px;min-height:44px;padding:9px 20px;color:#252b34;background:#fff;font:inherit;font-weight:600;cursor:pointer}\n.celebration-shortcut.current{background:#172033;color:white;border-color:#172033}\n.media-tabs,.media-filters{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:13px}\n.media-tab,.media-filter{border:1px solid #ddd;border-radius:28px;background:#fff;padding:11px 15px;min-height:42px;color:#313641;font:inherit;cursor:pointer}\n.media-tab.current{background:var(--frame-color);border-color:var(--frame-color);color:#fff}\n.media-filter.current{background:#172033;color:#fff;border-color:#172033}\n.media-list{display:grid;gap:16px}\n.media-card{border:1px solid #ddd;border-radius:23px;padding:18px;background:#fff;max-width:100%;min-width:0;overflow-wrap:anywhere}\n.media-location{display:block;font-size:13px;color:#626b77;text-transform:uppercase;font-weight:700;margin-bottom:10px}\n.media-card h3{margin:0 0 9px;font-size:19px;line-height:1.45;color:#202630}\n.media-description{white-space:pre-wrap;color:#6c7280;font-size:15px;margin:5px 0 16px}\n.media-cover{display:block;width:120px;max-height:120px;object-fit:contain;float:left;margin:0 15px 8px 0;border-radius:12px}\n.media-image{width:100%;height:auto;max-height:460px;object-fit:contain;border-radius:12px}\n.media-player{display:block;width:100%;margin:14px 0;clear:both}\n.media-seek{display:flex;gap:9px;justify-content:center;margin:14px 0}\n.media-small-button{min-width:100px;border:1px solid #aab4bc;border-radius:12px;padding:12px;background:#fff;font-weight:600;cursor:pointer}\n.media-repeat{display:flex;align-items:center;justify-content:center;gap:7px;margin-top:10px}\n.video-container{aspect-ratio:16/9;width:100%;margin-top:12px}\n.media-video{width:100%;aspect-ratio:16/9;border:0;border-radius:12px;background:#111}\n.media-document{display:block;border:1px solid #ccd1d6;border-radius:12px;padding:16px;text-decoration:none;color:#2c3138}\n.media-text{margin-top:13px}.media-text summary{cursor:pointer;padding:10px;border:1px solid #ddd;border-radius:8px}.media-text p{white-space:pre-wrap;line-height:1.65}\n@media(max-width:570px){.celebration-shortcut{min-width:0;flex:1;padding:9px}.media-tab{padding:10px;font-size:13px}.media-card{padding:15px}.media-cover{width:100px}}\n\n.celebration-shortcuts[hidden],.steps[hidden]{display:none!important}\n\n/* Mobile-first visual hierarchy: primary heading, secondary heading, paragraph, controls.\n   Authored font sizes set in the editor remain available and take precedence. */\n.trial-heading{font-family:Georgia,serif;font-size:clamp(21px,2.3vw,24px);font-weight:500;line-height:1.33;letter-spacing:-.015em;color:#29313a;margin:21px 0 10px;text-wrap:pretty}\n.trial-heading.heading-primary{font-size:clamp(26px,3vw,31px);font-weight:600;line-height:1.24;margin:0 0 19px}\n.trial-heading.heading-secondary{font-size:clamp(20px,2.3vw,24px);font-weight:500}\n.trial-heading.heading-schedule{font-size:clamp(22px,2.55vw,26px);font-weight:600;margin-top:30px}\n.trial-paragraph{font-size:16px;line-height:1.65;margin:7px 0 16px;color:#4b535b}\n.site-block{margin-bottom:18px}\n.trial-button,.media-document{font-size:15px;line-height:1.45;font-weight:600}\n.site-paper{padding:clamp(21px,3.7vw,44px)}\n.celebration-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;width:calc(100% - 24px);max-width:600px}\n.celebration-shortcut{box-sizing:border-box;min-width:0;max-width:100%;width:100%;padding:10px 7px;font-size:clamp(12px,1.8vw,15px);line-height:1.3;white-space:normal;overflow-wrap:break-word;text-align:center;display:flex;align-items:center;justify-content:center}\n.media-card h3{font-size:clamp(17px,2vw,20px);font-weight:650;line-height:1.38}\n.media-description{font-size:14px;line-height:1.55}\n.media-location{font-size:12px}\n.media-card{padding:clamp(13px,2.4vw,19px)}\n.media-tab,.media-filter{font-size:14px;line-height:1.35}\n.stage-tab{font-size:13px;line-height:1.35}\n@media(max-width:600px){\n .site-paper{padding:24px 19px;margin:9px 11px 32px}\n .trial-heading{font-size:21px}\n .trial-heading.heading-primary{font-size:27px}\n .trial-heading.heading-secondary{font-size:21px}\n .trial-heading.heading-schedule{font-size:23px}\n .trial-paragraph{font-size:16px;line-height:1.6}\n .celebration-shortcuts{gap:5px;width:calc(100% - 20px);padding:0 0}\n .celebration-shortcut{font-size:clamp(12px,3.35vw,13px);padding:10px 3px;min-height:46px}\n .media-tab{font-size:13px;padding:9px 11px}\n .media-filters .media-filter{font-size:13px}\n .media-card h3{font-size:18px}\n}\n\n/* Compact visitor library and smaller secondary links below the celebration days. */\n.celebration-shortcuts{display:flex;justify-content:center;align-items:center;gap:13px;max-width:none;width:auto;margin:8px 14px 16px;padding:0}\n.celebration-shortcut{display:inline-flex;width:auto;min-width:0;max-width:none;min-height:40px;border-radius:8px;background:transparent;color:#30353a;border:1px solid #dfe2e5;font-size:13px;font-weight:500;padding:8px 16px}\n.celebration-shortcut.current{background:#f2f3f4;color:#1b2735;border-color:#c8cfd4}\n.media-list{display:grid;grid-template-columns:1fr;gap:0}\n.compact-media{border:0;border-bottom:1px solid #e3e5e7;border-radius:0;padding:11px 5px;background:#fff}\n.compact-media .media-location{font-size:12px;margin:0 0 4px;color:#737b83}\n.media-item-link{display:block;max-width:100%;font-size:16px;font-weight:600;line-height:1.5;text-decoration:none;color:#263441;overflow-wrap:anywhere;padding:5px 0}\n.media-item-link:hover,.media-item-link:focus-visible{text-decoration:underline;color:#a1201d}\n.media-inline-player{padding:14px 4px 18px}\n.media-inline-player[hidden]{display:none!important}\n.media-image-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n.media-image-grid .compact-media{border:1px solid #e2e5e7;border-radius:12px;padding:10px}\n.media-image-link{display:block;aspect-ratio:4/3;overflow:hidden;background:#f6f7f8;border-radius:8px}\n.media-image-grid .media-image{display:block;width:100%;height:100%;object-fit:contain;max-height:none}\n.media-image-name{font-size:12px;line-height:1.45;color:#46505b;margin-top:9px}\n@media(max-width:900px){.media-image-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:560px){.media-image-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.media-item-link{font-size:15px}.celebration-shortcuts{gap:9px}.celebration-shortcut{font-size:13px;min-height:44px;padding:8px 15px}}\n\n.media-at-time{display:block;font-size:13px;font-weight:700;color:#4f5963;margin:4px 0 10px}\n\n/* Page composition: single block or two balanced desktop columns. */\n.trial-content-section{min-width:0;margin:14px 0 22px;padding:clamp(10px,2vw,22px)}\n.trial-content-columns{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;align-items:start}\n.trial-content-section[data-layout=\"columns\"]>.trial-content-columns{grid-template-columns:repeat(2,minmax(0,1fr))}\n.trial-content-column{min-width:0;overflow-wrap:anywhere}\n.trial-content-column .trial-figure{max-width:100%}\n.trial-content-column .trial-figure img{width:auto;max-width:100%;height:auto;object-fit:contain}\n.trial-content-column .trial-heading.heading-primary{font-size:clamp(23px,2.4vw,29px)}\n.trial-video{width:100%;max-width:100%;margin:12px 0}\n.trial-video-trigger{position:relative;display:block;width:100%;padding:0;background:#111;border:0;border-radius:12px;cursor:pointer;overflow:hidden}\n.trial-video-thumb{display:block;width:100%;aspect-ratio:16/9;object-fit:cover}\n.trial-video-play{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);border-radius:40px;background:#e21f1fd9;color:#fff;padding:13px 21px;font-size:25px}\n.trial-video-iframe,.trial-video-player{display:block;width:100%;aspect-ratio:16/9;border:0;border-radius:12px}\n.trial-video-title{font-size:16px;font-weight:600;margin:10px 0}\n.trial-site-link{display:block;min-width:0;max-width:100%;border:1px solid #e1e4e7;border-radius:13px;padding:12px;text-decoration:none;color:#26333b}\n.trial-site-cover{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;max-width:100%}\n.trial-website-card{display:flex;align-items:center;gap:9px;flex-wrap:wrap;min-height:90px;background:#f5f7f8;border-radius:9px;padding:14px}\n.trial-website-icon{height:34px;width:34px;object-fit:contain}.trial-website-domain{font-size:13px;color:#607080}\n@media(max-width:650px){.trial-content-section[data-layout=\"columns\"]>.trial-content-columns{grid-template-columns:minmax(0,1fr)}.trial-content-section{padding:10px}.trial-content-columns{gap:12px}}\n\n/* Visitor reading order: title first, small location afterwards. */\n.media-card.compact-media .media-location{font-size:11px;line-height:1.35;font-weight:450;letter-spacing:.01em;text-transform:none;color:#75808a;margin:3px 0 7px}\n.media-card.compact-media .media-item-link{font-size:16px;font-weight:650;margin:0;padding:3px 0}\n.media-card.compact-media .media-image-name{font-weight:650;margin:6px 0 0}\n.media-inline-player{position:relative}\n.media-video-close{position:absolute;right:9px;top:4px;z-index:5;width:34px;height:34px;border-radius:50%;border:1px solid #d1d5dc;background:#fff;color:#27353c;font-size:24px;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .12s}\n.media-inline-player:hover .media-video-close,.media-inline-player:focus-within .media-video-close{opacity:1;pointer-events:auto}\n.event-inline-time{display:inline;font:inherit;color:inherit;white-space:nowrap;margin-right:.2em}\n@media (hover:none){.media-inline-player .media-video-close{opacity:1;pointer-events:auto}}\n";
